"""Build review from actual 0.42 Godot captures, with authored timing playback."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
page='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cổ Sư · Nhịp đánh & thu thập 0.42</title>
<style>*{box-sizing:border-box}body{margin:0;background:#252d29;color:#eadbbc;font:16px/1.6 system-ui}main{max-width:1460px;margin:auto;padding:28px}h1{font-size:29px;line-height:1.2;margin:0 0 12px}h2{font-size:20px}p{max-width:1000px;color:#c8c7b5}a{color:#e9ce9e}nav{display:flex;gap:22px;flex-wrap:wrap;padding-bottom:20px;margin-bottom:24px;border-bottom:1px solid #576351}.controls{display:flex;gap:12px;flex-wrap:wrap;align-items:end}label{display:grid;gap:5px;font-size:13px}select,button{font:inherit;color:#eadbbc;background:#354139;border:1px solid #8a967f;border-radius:4px;min-height:42px;padding:7px 12px}button{cursor:pointer}button:disabled{opacity:.5}:focus-visible{outline:2px solid #e7c18c;outline-offset:3px}.scrub{display:flex;gap:14px;align-items:center;margin:18px 0}input{accent-color:#cfb887;flex:1;min-width:0}output{font-variant-numeric:tabular-nums;min-width:80px}.detail{display:flex;gap:28px;flex-wrap:wrap;align-items:center}.crop{position:relative;width:320px;height:270px;overflow:hidden;background:#354139;border:1px solid #576351;flex:none}.crop img{position:absolute;width:2560px;height:900px;max-width:none}.note{max-width:730px}.full{width:100%;height:auto;display:block;border:1px solid #576351;margin-top:20px}.legend{font-size:14px;color:#bbae91}details{margin:20px 0}summary{cursor:pointer;padding:12px 0;font-weight:600}@media(max-width:650px){main{padding:16px}h1{font-size:24px}.detail{gap:12px}}</style>
<main><h1>Vung kiếm có nhịp. Thu thập có động tác.</h1><p>0.42 · Lấy đà → ra đòn → theo đà → thu tay. Chân giữ điểm tựa; tay phụ, đầu và vạt áo phản ứng lệch nhịp nhẹ. Hai động tác thu thập dùng bàn tay và cuốc riêng, trả lại vũ khí đã trang bị khi kết thúc.</p>
<nav><a href="#world">Thao tác E trong game</a><a href="#references">Video & tài liệu tham khảo</a><a href="concept42_motion.json">Kiểm khớp & chân trụ</a><a href="concept41_character_review.html">Bản trước · 0.41</a></nav>
<div class="controls"><label>Động tác<select id="action"><option value="attack">Vung kiếm</option><option value="gather">Hái lượm</option><option value="mine">Khai khoáng</option></select></label><label>Giới tính<select id="body"><option value="0">Nam</option><option value="1">Nữ</option></select></label><label>Hướng<select id="direction"></select></label><label>Tốc độ<select id="speed"><option value="1">Nhịp trong game · 1×</option><option value=".5">Chậm · ½×</option><option value=".25">Rất chậm · ¼×</option></select></label><label>Lớp xem<select id="bones"><option value="0">Hình nhân vật</option><option value="1">Khớp xương</option></select></label><button id="prev" aria-label="Frame trước">←</button><button id="play">Phát</button><button id="next" aria-label="Frame sau">→</button></div>
<div class="scrub"><input id="slider" type="range" min="0" max="31" value="11" aria-label="Chọn frame"><output id="count"></output></div>
<div class="detail"><div class="crop"><img id="focus" alt="Chi tiết nhân vật theo góc đã chọn"></div><div class="note"><h2 id="name"></h2><p id="status"></p><p id="motion"></p><p class="legend">32 ảnh mẫu mỗi động tác, chụp từ playback thật của Godot cho cả nam/nữ ở 8 hướng. Runtime nội suy liên tục. Lớp xương có bốn mốc chụp, không phải overlay của mọi frame.</p><a id="original" href="">Mở ảnh gốc đủ 16 góc</a></div></div>
<img class="full" id="full" alt="Nam và nữ ở tám hướng">
<details id="world"><summary>Thu thập bằng phím E và xem động tác trong F6</summary><p>Phím E bên cạnh tài nguyên: hái cây hoặc cuốc quặng. Di chuyển, trúng đòn hay dùng Cổ ngắt động tác. Phần thưởng vẫn do sự kiện game xử lý một lần; animation không tự cấp vật phẩm.</p><img class="full" src="concept42_world_gather_30.png" alt="Hái tài nguyên trong game"><img class="full" src="concept42_world_mine_30.png" alt="Khai khoáng trong game"><img class="full" src="concept42_studio_mine.png" alt="Xưởng nhân vật có động tác khai khoáng"><a href="concept42_ingame.json">Kết quả kiểm tra input thật</a></details>
<details id="references"><summary>Tham khảo Klei — áp dụng vào nhân vật Cổ Sư</summary><p>Đã kiểm các đoạn gameplay trồng trọt (khoảng 26–29 giây) và chiến đấu (khoảng 33 giây) của <a href="https://www.youtube.com/watch?v=dU-aq2JbLkk">trailer chính thức Don’t Starve Together</a>. Đã đọc <a href="https://media.gdcvault.com/GDC2014/Presentations/Agala_Jeff_2D_Animation_at.pdf">slide GDC của Jeff Agala và Aaron Bouthillier</a>: tư thế chính, chi tiết theo khớp, thư viện hình và nội suy theo lớp. <a href="https://www.youtube.com/watch?v=8_KBjd0iaCU">Video bài nói GDC</a> để xem thêm.</p><p>Nhịp 0,64 / 0,88 / 0,96 giây và các đường cong ở đây được thiết kế cho nhân vật hiện tại. Đây là chuyển động rig của Cổ Sư, không phải bộ frame trích từ DST hay bản sao chuyển động 1:1.</p></details></main>
<script>
const $=id=>document.getElementById(id),dirs=['S · xuống','SW · xuống trái','W · trái','NW · lên trái','N · lên','NE · lên phải','E · phải','SE · xuống phải'],durations={attack:.64,gather:.88,mine:.96},contacts={attack:.34,gather:.5,mine:.48},notes={attack:'Thân và tay cùng nhịp; cổ tay không bị bộ lò xo kéo chậm sau điểm chạm. Nguyệt Nhận rời bàn tay ở pha ra đòn.',gather:'Hạ người, đưa tay tới, nắm rồi rút về. Tay phụ giữ thăng bằng; hai bàn chân bám đất.',mine:'Giơ cuốc, giữ lấy đà ngắn, bổ xuống và thu tay. Cuốc gắn vào bàn tay; chuẩn bị giấu sau lớp đầu khi đi qua vùng mặt.'};let timer=null,frame=11,loaded=new Set(),generation=0;
dirs.forEach((text,d)=>$('direction').add(new Option(text,d)));$('direction').value='6';
function url(n,bones=false){return bones?`concept42_${$('action').value}_bones_${String(n).padStart(2,'0')}.png`:`concept42_${$('action').value}/frame${String(n).padStart(3,'0')}.png`}
function update(){const a=$('action').value,b=+$('body').value,d=+$('direction').value,overlay=$('bones').value==='1';let n=frame;if(overlay)n=[5,11,16,24].reduce((best,x)=>Math.abs(x-frame)<Math.abs(best-frame)?x:best,5);const source=url(n,overlay);$('focus').src=$('full').src=$('original').href=source;$('focus').style.left=`${-d*320}px`;$('focus').style.top=`${-(105+b*370)}px`;$('slider').value=frame;$('count').textContent=`${n+1} / 32`;$('name').textContent=`${b?'Nữ':'Nam'} · ${dirs[d]} · ${$('action').selectedOptions[0].text}`;const phase=n/32,beat=phase<.16?'Lấy đà':phase<contacts[a]?'Tiếp cận / ra đòn':phase<.64?'Theo đà / rút tay':'Thu về';$('status').textContent=`${beat} · ${(phase*durations[a]).toFixed(3)} / ${durations[a].toFixed(2)} giây${overlay?' · mốc xương gần nhất':''}`;$('motion').textContent=notes[a];}
function stop(){clearInterval(timer);timer=null;$('play').textContent='Phát'}
function step(delta){frame=(frame+delta+32)%32;update()}
async function prepare(){const a=$('action').value,gen=++generation;$('play').disabled=true;if(!loaded.has(a)){await Promise.all(Array.from({length:32},(_,n)=>new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=reject;img.src=`concept42_${a}/frame${String(n).padStart(3,'0')}.png`;})));loaded.add(a)}if(gen===generation)$('play').disabled=false;}
function play(){if(timer){stop();return}timer=setInterval(()=>step(1),durations[$('action').value]*1000/32/+$('speed').value);$('play').textContent='Dừng'}
$('play').onclick=play;$('prev').onclick=()=>{stop();step(-1)};$('next').onclick=()=>{stop();step(1)};$('slider').oninput=()=>{stop();frame=+$('slider').value;update()};for(const id of ['action','body','direction','bones'])$(id).onchange=()=>{stop();update();if(id==='action')prepare().catch(()=>{$('status').textContent='Không tải được một số frame.'})};$('speed').onchange=()=>{if(timer){stop();play()}};document.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();if(!$('play').disabled)play()}if(e.key==='ArrowRight'){stop();step(1)}if(e.key==='ArrowLeft'){stop();step(-1)}});update();prepare().catch(()=>{$('status').textContent='Không tải được frame. Hãy tải lại trang.'});
</script></html>'''
(ROOT/'artifacts/concept42_action_review.html').write_text(page)
print('Built native action review 0.42')
